-- Stored procedures generated by `npm run db:fn-migration` from prisma/functions/.
-- Edit the source files, not this migration.

-- ───────────── Signature changes (hand-written: README "Two cases need a hand-written migration")
-- CREATE OR REPLACE cannot change a function's return type, and adding a parameter would leave
-- the old function behind as an overload. These are dropped so the definitions below install
-- cleanly.
--   fn_create_post / fn_get_post / fn_get_home_feed / fn_get_profile_posts  + post type (PHOTO | VIDEO)
--   fn_get_post_comments                                                   + reply_count
--   fn_delete_comment                                                      + parent_reply_count
--   fn_add_comment                                                         + p_parent_id (new arity)
DROP FUNCTION IF EXISTS fn_create_post(uuid, uuid[], text, text, text);
DROP FUNCTION IF EXISTS fn_get_post(uuid, uuid);
DROP FUNCTION IF EXISTS fn_get_home_feed(uuid, timestamptz, uuid, int);
DROP FUNCTION IF EXISTS fn_get_profile_posts(uuid, text, timestamptz, uuid, int);
DROP FUNCTION IF EXISTS fn_get_post_comments(uuid, uuid, timestamptz, uuid, int);
DROP FUNCTION IF EXISTS fn_delete_comment(uuid, uuid);
DROP FUNCTION IF EXISTS fn_add_comment(uuid, uuid, text, text, text);
--   fn_complete_media_processing                                           + p_duration_ms (new arity)
DROP FUNCTION IF EXISTS fn_complete_media_processing(uuid, int, int, text, jsonb);

-- @function _common/fn__sync_post_hashtags.sql
-- Rewrites a post's hashtags from its caption (BR-FD-10). Called by fn_create_post and
-- fn_update_post_caption, so a post's tags always match the caption that is stored.
--
-- A tag is '#' followed by 1-64 letters, digits or underscores, and the '#' must not sit right
-- after one of those characters: "(#dar)" and "#dar_es" are tags, "C#" and "a#b" are not. Tags
-- are stored without the '#' and compared case-insensitively (the column is citext), so
-- "#DAR #dar" in one caption is one tag on the post. At most 30 distinct tags are kept, in
-- alphabetical order; a caption stuffed with more is not an error, the rest are ignored.
CREATE OR REPLACE FUNCTION fn__sync_post_hashtags(p_post_id uuid, p_caption text)
RETURNS void
LANGUAGE sql VOLATILE
SET search_path = public, pg_temp
AS $$
  WITH wanted AS (
    SELECT DISTINCT m[1]::citext AS tag
    FROM regexp_matches(COALESCE(p_caption, ''), '(?:^|[^[:alnum:]_])#([[:alnum:]_]{1,64})', 'g') AS m
    ORDER BY tag
    LIMIT 30
  ),
  -- A tag row is created the first time anyone uses it and never removed: it costs a few bytes
  -- and keeps older /t/<tag> links working. ON CONFLICT makes two posts introducing the same new
  -- tag in the same instant safe.
  created AS (
    INSERT INTO hashtags (tag) SELECT w.tag FROM wanted w
    ON CONFLICT (tag) DO NOTHING
    RETURNING id
  ),
  -- This statement's snapshot predates `created`, so the tags it just inserted have to be
  -- unioned in rather than read back from the table.
  ids AS MATERIALIZED (
    SELECT h.id FROM hashtags h JOIN wanted w ON w.tag = h.tag
    UNION
    SELECT c.id FROM created c
  ),
  dropped AS (
    DELETE FROM post_hashtags ph
    WHERE ph.post_id = p_post_id AND ph.hashtag_id NOT IN (SELECT i.id FROM ids i)
  )
  INSERT INTO post_hashtags (post_id, hashtag_id)
  SELECT p_post_id, i.id FROM ids i
  ON CONFLICT DO NOTHING;
$$;
-- @end-function

-- @function admin/fn_admin_set_comment_hidden.sql
-- POST /admin/comments/:id/hide · /unhide (BR-SF-03). The post's comment_count follows.
-- Deleted comments cannot change (JA409 INVALID_STATE). Logged in moderation_actions; closes
-- p_report_id if given.
--
-- Hiding a top-level comment also takes its replies out of the count (BR-FD-08): a reply is only
-- ever read through its parent, so a hidden parent hides the thread. The replies' own hidden_at
-- is deliberately left alone, so unhiding restores exactly the replies that are still visible in
-- their own right — a reply hidden separately by a moderator stays hidden.
CREATE OR REPLACE FUNCTION fn_admin_set_comment_hidden(
  p_admin_id uuid, p_comment_id uuid, p_hidden boolean, p_note text, p_report_id uuid DEFAULT NULL)
RETURNS TABLE (comment_id uuid, hidden boolean)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  k               comments%ROWTYPE;
  v_parent_hidden boolean := false;
  v_counted       int := 0;
BEGIN
  PERFORM fn__assert_admin(p_admin_id, ARRAY['SUPER_ADMIN', 'MODERATOR']::admin_role[]);
  PERFORM fn__require_note(p_note);

  SELECT * INTO k FROM comments x WHERE x.id = p_comment_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'COMMENT_NOT_FOUND';
  ELSIF k.deleted_at IS NOT NULL OR (k.hidden_at IS NOT NULL) = p_hidden THEN
    RAISE EXCEPTION USING ERRCODE = 'JA409', MESSAGE = 'INVALID_STATE';
  END IF;

  UPDATE comments x SET hidden_at = CASE WHEN p_hidden THEN now() END WHERE x.id = p_comment_id;

  IF k.parent_id IS NULL THEN
    -- This comment, plus the replies that are visible in their own right.
    SELECT 1 + count(*)::int INTO v_counted
    FROM comments x
    WHERE x.parent_id = p_comment_id AND x.deleted_at IS NULL AND x.hidden_at IS NULL;
  ELSE
    -- A reply under an already hidden or deleted parent was not being counted, so hiding or
    -- restoring it changes nothing on the post.
    SELECT (x.hidden_at IS NOT NULL OR x.deleted_at IS NOT NULL) INTO v_parent_hidden
    FROM comments x WHERE x.id = k.parent_id FOR UPDATE;
    v_counted := CASE WHEN v_parent_hidden THEN 0 ELSE 1 END;
    UPDATE comments x SET reply_count = GREATEST(x.reply_count + CASE WHEN p_hidden THEN -1 ELSE 1 END, 0)
    WHERE x.id = k.parent_id;
  END IF;

  IF v_counted > 0 THEN
    UPDATE posts p
    SET comment_count = GREATEST(p.comment_count + CASE WHEN p_hidden THEN -v_counted ELSE v_counted END, 0)
    WHERE p.id = k.post_id;
  END IF;

  PERFORM fn__close_report(p_report_id, p_admin_id);
  INSERT INTO moderation_actions (admin_id, action, report_id, target_user_id, target_comment_id, note)
  VALUES (p_admin_id, CASE WHEN p_hidden THEN 'HIDE_COMMENT' ELSE 'UNHIDE_COMMENT' END::moderation_action_type,
          p_report_id, k.author_id, p_comment_id, btrim(p_note));

  RETURN QUERY SELECT p_comment_id, p_hidden;
END $$;
-- @end-function

-- @function engagement/fn_add_comment.sql
-- POST /posts/:id/comments (BR-FD-04, API-08). The post must be visible to the viewer (else
-- JA404). Idempotency-Key works as in fn_create_post: a repeat returns the original comment.
--
-- p_parent_id (BR-FD-08/09) makes this a reply. Replies are ONE level deep: replying to a reply
-- answers that reply's parent instead, so the row written always points at a top-level comment.
-- The parent must be on the same post and still visible, otherwise JA404 COMMENT_NOT_FOUND.
--
-- Counters: the post's comment_count counts replies as well as top-level comments, and the
-- parent's reply_count counts its visible replies.
--
-- notification_id: who gets told. A top-level comment tells the post's author (COMMENT); a reply
-- tells the author of the comment it answers (REPLY) and NOT the post's author, so one reply is
-- never two notifications. Nobody is ever told about their own action.
CREATE OR REPLACE FUNCTION fn_add_comment(
  p_viewer_id       uuid,
  p_post_id         uuid,
  p_body            text,
  p_parent_id       uuid,
  p_idempotency_key text,
  p_request_hash    text)
RETURNS TABLE (
  comment_id uuid, post_id uuid, parent_id uuid, body varchar, created_at timestamptz,
  comment_count int, parent_reply_count int, notification_id uuid, replayed boolean)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  c_route      constant text := 'POST /posts/:id/comments';
  v_replay       jsonb;
  v_comment_id   uuid;
  v_count        int;
  v_author_id    uuid;
  v_notif_id     uuid;
  v_parent       comments%ROWTYPE;
  v_parent_id    uuid;
  v_reply_count  int;
  v_notify       uuid;
  v_notify_type  notification_type;
BEGIN
  PERFORM fn__assert_active_user(p_viewer_id);

  IF p_idempotency_key IS NOT NULL THEN
    v_replay := fn__claim_idempotency_key(p_viewer_id, p_idempotency_key, c_route, p_request_hash);
    IF v_replay IS NOT NULL THEN
      RETURN QUERY
      SELECT c.id, c.post_id, c.parent_id, c.body, c.created_at, p.comment_count,
             COALESCE(k.reply_count, 0), NULL::uuid, true
      FROM comments c
      JOIN posts p ON p.id = c.post_id
      LEFT JOIN comments k ON k.id = c.parent_id
      WHERE c.id = (v_replay->>'commentId')::uuid;
      RETURN;
    END IF;
  END IF;

  v_author_id := fn__assert_post_visible(p_viewer_id, p_post_id);

  IF p_parent_id IS NOT NULL THEN
    SELECT * INTO v_parent FROM comments k WHERE k.id = p_parent_id FOR UPDATE;
    IF NOT FOUND OR v_parent.post_id <> p_post_id
       OR v_parent.deleted_at IS NOT NULL OR v_parent.hidden_at IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'COMMENT_NOT_FOUND';
    END IF;
    -- One level only: a reply to a reply answers the top-level comment above it.
    v_parent_id := COALESCE(v_parent.parent_id, v_parent.id);
    IF v_parent_id <> p_parent_id THEN
      SELECT * INTO v_parent FROM comments k WHERE k.id = v_parent_id FOR UPDATE;
      IF NOT FOUND OR v_parent.deleted_at IS NOT NULL OR v_parent.hidden_at IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'COMMENT_NOT_FOUND';
      END IF;
    END IF;
    -- A blocked person's comment is invisible, so it cannot be answered either.
    IF fn__is_blocked_either_way(p_viewer_id, v_parent.author_id) THEN
      RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'COMMENT_NOT_FOUND';
    END IF;
  END IF;

  INSERT INTO comments (post_id, author_id, parent_id, body)
  VALUES (p_post_id, p_viewer_id, v_parent_id, btrim(p_body))
  RETURNING id INTO v_comment_id;

  UPDATE posts p SET comment_count = p.comment_count + 1 WHERE p.id = p_post_id
  RETURNING p.comment_count INTO v_count;

  IF v_parent_id IS NOT NULL THEN
    UPDATE comments k SET reply_count = k.reply_count + 1 WHERE k.id = v_parent_id
    RETURNING k.reply_count INTO v_reply_count;
    v_notify := v_parent.author_id;
    v_notify_type := 'REPLY';
  ELSE
    v_notify := v_author_id;
    v_notify_type := 'COMMENT';
  END IF;

  IF v_notify <> p_viewer_id THEN
    INSERT INTO notifications (recipient_id, actor_id, type, post_id, comment_id)
    VALUES (v_notify, p_viewer_id, v_notify_type, p_post_id, v_comment_id)
    RETURNING id INTO v_notif_id;
  END IF;

  IF p_idempotency_key IS NOT NULL THEN
    UPDATE idempotency_keys k SET response_body = jsonb_build_object('commentId', v_comment_id)
    WHERE k.user_id = p_viewer_id AND k.key = p_idempotency_key;
  END IF;

  RETURN QUERY
  SELECT c.id, c.post_id, c.parent_id, c.body, c.created_at, v_count,
         COALESCE(v_reply_count, 0), v_notif_id, false
  FROM comments c WHERE c.id = v_comment_id;
END $$;
-- @end-function

-- @function engagement/fn_delete_comment.sql
-- DELETE /comments/:id (BR-FD-05): by the comment's author or the post's author. Soft delete,
-- purged after 30 days. A comment the viewer cannot see is JA404; one they see but may not
-- delete is JA403 NOT_OWNER.
--
-- Deleting a top-level comment deletes the thread under it (BR-FD-08): its replies would
-- otherwise be unreachable, since a reply is only ever read through its parent.
--
-- Counters. A reply counts towards its post's comment_count only while BOTH it and its parent
-- are visible, which is the rule fn_maint_reconcile_counters recomputes; deleting a reply under
-- an already hidden parent therefore changes no count. reply_count follows the replies' own
-- state and ignores whether the parent is hidden.
CREATE OR REPLACE FUNCTION fn_delete_comment(p_viewer_id uuid, p_comment_id uuid)
RETURNS TABLE (deleted boolean, comment_count int, parent_reply_count int)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  c               comments%ROWTYPE;
  v_post_author   uuid;
  v_count         int;
  v_parent_hidden boolean := false;
  v_uncounted     int := 0;
  v_replies       int := 0;
  v_reply_count   int;
BEGIN
  PERFORM fn__assert_active_user(p_viewer_id);

  SELECT * INTO c FROM comments k WHERE k.id = p_comment_id FOR UPDATE;
  IF NOT FOUND OR c.deleted_at IS NOT NULL
     OR (c.author_id <> p_viewer_id AND c.hidden_at IS NOT NULL) THEN
    RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'COMMENT_NOT_FOUND';
  END IF;
  SELECT p.author_id INTO v_post_author FROM posts p WHERE p.id = c.post_id;

  IF p_viewer_id NOT IN (c.author_id, v_post_author) THEN
    -- Reveal nothing about comments on posts the viewer cannot see.
    BEGIN
      PERFORM fn__assert_post_visible(p_viewer_id, c.post_id);
    EXCEPTION WHEN SQLSTATE 'JA404' THEN
      RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'COMMENT_NOT_FOUND';
    END;
    RAISE EXCEPTION USING ERRCODE = 'JA403', MESSAGE = 'NOT_OWNER';
  END IF;

  IF c.parent_id IS NOT NULL THEN
    SELECT (k.hidden_at IS NOT NULL OR k.deleted_at IS NOT NULL) INTO v_parent_hidden
    FROM comments k WHERE k.id = c.parent_id FOR UPDATE;
  END IF;

  UPDATE comments k SET deleted_at = now() WHERE k.id = p_comment_id;

  IF c.parent_id IS NULL THEN
    -- Take the thread with it, and stop counting every reply that was still being counted.
    WITH gone AS (
      UPDATE comments k SET deleted_at = now()
      WHERE k.parent_id = p_comment_id AND k.deleted_at IS NULL
      RETURNING k.hidden_at
    )
    SELECT (count(*) FILTER (WHERE hidden_at IS NULL))::int INTO v_replies FROM gone;
    UPDATE comments k SET reply_count = 0 WHERE k.id = p_comment_id;
    -- The comment itself counted only while it was visible.
    v_uncounted := v_replies + CASE WHEN c.hidden_at IS NULL THEN 1 ELSE 0 END;
    v_reply_count := 0;
  ELSE
    IF c.hidden_at IS NULL THEN
      UPDATE comments k SET reply_count = GREATEST(k.reply_count - 1, 0) WHERE k.id = c.parent_id
      RETURNING k.reply_count INTO v_reply_count;
      IF NOT v_parent_hidden THEN
        v_uncounted := 1;
      END IF;
    ELSE
      SELECT k.reply_count INTO v_reply_count FROM comments k WHERE k.id = c.parent_id;
    END IF;
  END IF;

  IF v_uncounted > 0 THEN
    UPDATE posts p SET comment_count = GREATEST(p.comment_count - v_uncounted, 0) WHERE p.id = c.post_id
    RETURNING p.comment_count INTO v_count;
  ELSE
    SELECT p.comment_count INTO v_count FROM posts p WHERE p.id = c.post_id;
  END IF;

  RETURN QUERY SELECT true, v_count, COALESCE(v_reply_count, 0);
END $$;
-- @end-function

-- @function engagement/fn_get_comment_replies.sql
-- GET /comments/:id/replies (BR-FD-08). The replies under one comment, OLDEST first, because a
-- thread under a comment reads as a conversation rather than as a feed; cursor = the last row's
-- (created_at, comment_id) and the keyset predicate runs the other way round from every other
-- list in this schema, so fn__cursor's 'infinity' sentinel is not used here.
-- The parent must itself be visible to the viewer, and a reply from someone blocked either way,
-- or whose author is not ACTIVE, is left out.
-- can_delete: the viewer wrote the reply or owns the post.
CREATE OR REPLACE FUNCTION fn_get_comment_replies(
  p_viewer_id   uuid,
  p_comment_id  uuid,
  p_cursor_time timestamptz DEFAULT NULL,
  p_cursor_id   uuid        DEFAULT NULL,
  p_limit       int         DEFAULT 20)
RETURNS TABLE (
  comment_id uuid, body varchar, created_at timestamptz,
  author_id uuid, author_username citext, author_display_name varchar, author_avatar_key text,
  can_delete boolean)
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  v_parent      comments%ROWTYPE;
  v_post_author uuid;
  v_time        timestamptz := COALESCE(p_cursor_time, '-infinity'::timestamptz);
  v_id          uuid        := COALESCE(p_cursor_id, '00000000-0000-0000-0000-000000000000'::uuid);
  v_limit       int         := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 50) + 1;
BEGIN
  PERFORM fn__assert_active_user(p_viewer_id);

  SELECT * INTO v_parent FROM comments k WHERE k.id = p_comment_id;
  IF NOT FOUND OR v_parent.parent_id IS NOT NULL
     OR v_parent.deleted_at IS NOT NULL OR v_parent.hidden_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'COMMENT_NOT_FOUND';
  END IF;
  v_post_author := fn__assert_post_visible(p_viewer_id, v_parent.post_id);
  IF fn__is_blocked_either_way(p_viewer_id, v_parent.author_id) THEN
    RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'COMMENT_NOT_FOUND';
  END IF;

  RETURN QUERY
  SELECT k.id, k.body, k.created_at,
         u.id, u.username, u.display_name, av.object_key,
         p_viewer_id IN (k.author_id, v_post_author)
  FROM comments k
  JOIN users u ON u.id = k.author_id AND u.status = 'ACTIVE'
  LEFT JOIN media_variants av ON av.media_id = u.avatar_media_id AND av.variant = 'AVATAR_S'
  WHERE k.parent_id = p_comment_id
    AND k.deleted_at IS NULL AND k.hidden_at IS NULL
    AND (k.created_at, k.id) > (v_time, v_id)
    AND NOT EXISTS (SELECT 1 FROM blocks b
                    WHERE (b.blocker_id = p_viewer_id AND b.blocked_id = k.author_id)
                       OR (b.blocker_id = k.author_id AND b.blocked_id = p_viewer_id))
  ORDER BY k.created_at ASC, k.id ASC
  LIMIT v_limit;
END $$;
-- @end-function

-- @function engagement/fn_get_post_comments.sql
-- GET /posts/:id/comments (BR-FD-04/05). The post's TOP-LEVEL comments, newest first (the app
-- shows them newest first too); cursor = the last row's (created_at, comment_id). Replies are
-- not in this list: they are fetched per comment by fn_get_comment_replies (BR-FD-08).
-- Hides hidden / deleted comments, authors who are not ACTIVE and users blocked either way.
-- can_delete: the viewer wrote the comment or owns the post.
-- reply_count is the stored counter, which does not know the viewer's blocks, so a thread can
-- open with fewer replies than the count promised. It is a count, not a guarantee.
CREATE OR REPLACE FUNCTION fn_get_post_comments(
  p_viewer_id   uuid,
  p_post_id     uuid,
  p_cursor_time timestamptz DEFAULT NULL,
  p_cursor_id   uuid        DEFAULT NULL,
  p_limit       int         DEFAULT 20)
RETURNS TABLE (
  comment_id uuid, body varchar, created_at timestamptz, reply_count int,
  author_id uuid, author_username citext, author_display_name varchar, author_avatar_key text,
  can_delete boolean)
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  v_post_author uuid;
  c             record := fn__cursor(p_cursor_time, p_cursor_id, p_limit);
BEGIN
  PERFORM fn__assert_active_user(p_viewer_id);
  v_post_author := fn__assert_post_visible(p_viewer_id, p_post_id);

  RETURN QUERY
  SELECT k.id, k.body, k.created_at, k.reply_count,
         u.id, u.username, u.display_name, av.object_key,
         p_viewer_id IN (k.author_id, v_post_author)
  FROM comments k
  JOIN users u ON u.id = k.author_id AND u.status = 'ACTIVE'
  LEFT JOIN media_variants av ON av.media_id = u.avatar_media_id AND av.variant = 'AVATAR_S'
  WHERE k.post_id = p_post_id
    AND k.parent_id IS NULL
    AND k.deleted_at IS NULL AND k.hidden_at IS NULL
    AND (k.created_at, k.id) < (c.cursor_time, c.cursor_id)
    AND NOT EXISTS (SELECT 1 FROM blocks b
                    WHERE (b.blocker_id = p_viewer_id AND b.blocked_id = k.author_id)
                       OR (b.blocker_id = k.author_id AND b.blocked_id = p_viewer_id))
  ORDER BY k.created_at DESC, k.id DESC
  LIMIT c.page_limit;
END $$;
-- @end-function

-- @function feed/fn_get_hashtag_posts.sql
-- GET /tags/:tag/posts (BR-FD-11). The posts carrying one tag, newest first, as grid tiles.
-- Visibility matches the feed and the profile grid: PUBLISHED posts only, author ACTIVE, and
-- nothing either way across a block — so a tag never becomes a way around a block.
-- Unlike the home feed this is NOT limited to people the viewer follows: a tag is how the pilot
-- finds posts from accounts it does not follow yet.
-- An unknown tag is not an error, it is an empty page, which is also what the screen shows for a
-- tag whose every post is gone. post_count repeats on each row and counts every PUBLISHED post
-- on the tag BEFORE the viewer's own blocks are applied, so the header reads the same for
-- everyone and tells nobody who blocked whom; an empty page carries no count, and the API
-- reports 0.
CREATE OR REPLACE FUNCTION fn_get_hashtag_posts(
  p_viewer_id   uuid,
  p_tag         text,
  p_cursor_time timestamptz DEFAULT NULL,
  p_cursor_id   uuid        DEFAULT NULL,
  p_limit       int         DEFAULT 20)
RETURNS TABLE (
  post_id uuid, status post_status, type post_type, thumb_key text, blurhash varchar,
  media_count int, created_at timestamptz, tag citext, post_count int)
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  v_tag        citext := NULLIF(btrim(ltrim(btrim(COALESCE(p_tag, '')), '#')), '')::citext;
  v_hashtag_id uuid;
  v_count      int := 0;
  c            record := fn__cursor(p_cursor_time, p_cursor_id, p_limit);
BEGIN
  PERFORM fn__assert_active_user(p_viewer_id);

  IF v_tag IS NULL OR v_tag !~ '^[[:alnum:]_]{1,64}$' THEN
    RAISE EXCEPTION USING ERRCODE = 'JA400', MESSAGE = 'TAG_INVALID';
  END IF;

  SELECT h.id INTO v_hashtag_id FROM hashtags h WHERE h.tag = v_tag;
  IF v_hashtag_id IS NULL THEN
    RETURN;
  END IF;

  SELECT count(*)::int INTO v_count
  FROM post_hashtags ph
  JOIN posts p ON p.id = ph.post_id AND p.status = 'PUBLISHED'
  JOIN users u ON u.id = p.author_id AND u.status = 'ACTIVE'
  WHERE ph.hashtag_id = v_hashtag_id;

  RETURN QUERY
  SELECT p.id, p.status, p.type, tv.object_key, ma.blurhash,
         (SELECT count(*)::int FROM post_media x WHERE x.post_id = p.id),
         p.created_at, v_tag, v_count
  FROM post_hashtags ph
  JOIN posts p ON p.id = ph.post_id AND p.status = 'PUBLISHED'
  JOIN users u ON u.id = p.author_id AND u.status = 'ACTIVE'
  LEFT JOIN post_media pm ON pm.post_id = p.id AND pm.position = 0
  LEFT JOIN media_assets ma ON ma.id = pm.media_id
  LEFT JOIN media_variants tv ON tv.media_id = pm.media_id AND tv.variant = 'THUMB'
  WHERE ph.hashtag_id = v_hashtag_id
    AND (p.created_at, p.id) < (c.cursor_time, c.cursor_id)
    AND NOT EXISTS (SELECT 1 FROM blocks b
                    WHERE (b.blocker_id = p_viewer_id AND b.blocked_id = p.author_id)
                       OR (b.blocker_id = p.author_id AND b.blocked_id = p_viewer_id))
  ORDER BY p.created_at DESC, p.id DESC
  LIMIT c.page_limit;
END $$;
-- @end-function

-- @function feed/fn_get_home_feed.sql
-- GET /feed (BR-FD-01/02, TRD §10; reference implementation Schema §8.1). Fan-out on read:
-- PUBLISHED posts of followed users and the viewer's own, author ACTIVE, no block either way,
-- newest first. One round trip, already joined with author, media variants and liked_by_me.
-- Returns limit + 1 rows; the API builds nextCursor from the extra row.
--
-- `media` is the post's items in carousel order (BR-CT-09). A photo carries feedKey; a video
-- carries videoKey (the 720p MP4), posterKey and durationMs (BR-CT-08). Both carry thumbKey,
-- and width/height describe whichever of the two is there, so the card can reserve its space.
CREATE OR REPLACE FUNCTION fn_get_home_feed(
  p_viewer_id   uuid,
  p_cursor_time timestamptz DEFAULT NULL,
  p_cursor_id   uuid        DEFAULT NULL,
  p_limit       int         DEFAULT 20)
RETURNS TABLE (
  post_id uuid, created_at timestamptz, type post_type, caption varchar, like_count int,
  comment_count int, liked_by_me boolean, author_id uuid, author_username citext,
  author_display_name varchar, author_avatar_key text, media jsonb)
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  c record := fn__cursor(p_cursor_time, p_cursor_id, p_limit);
BEGIN
  PERFORM fn__assert_active_user(p_viewer_id);

  RETURN QUERY
  WITH authors AS (
    SELECT f.following_id AS id FROM follows f WHERE f.follower_id = p_viewer_id
    UNION ALL
    SELECT p_viewer_id
  ),
  -- Top page_limit posts per author through posts_published_author_created_idx, then the newest
  -- page_limit of those: at most (follows + 1) × page_limit index rows, however long the history.
  page AS (
    SELECT x.id, x.author_id, x.type, x.caption, x.like_count, x.comment_count, x.created_at
    FROM authors a
    JOIN users u ON u.id = a.id AND u.status = 'ACTIVE'
    CROSS JOIN LATERAL (
      SELECT p.id, p.author_id, p.type, p.caption, p.like_count, p.comment_count, p.created_at
      FROM posts p
      WHERE p.author_id = a.id
        AND p.status = 'PUBLISHED'
        AND (p.created_at, p.id) < (c.cursor_time, c.cursor_id)
      ORDER BY p.created_at DESC, p.id DESC
      LIMIT c.page_limit
    ) x
    WHERE NOT EXISTS (SELECT 1 FROM blocks b
                      WHERE (b.blocker_id = p_viewer_id AND b.blocked_id = a.id)
                         OR (b.blocker_id = a.id AND b.blocked_id = p_viewer_id))
    ORDER BY x.created_at DESC, x.id DESC
    LIMIT c.page_limit
  )
  SELECT pg.id, pg.created_at, pg.type, pg.caption, pg.like_count, pg.comment_count,
         EXISTS (SELECT 1 FROM likes l WHERE l.user_id = p_viewer_id AND l.post_id = pg.id),
         u.id, u.username, u.display_name, av.object_key,
         m.media
  FROM page pg
  JOIN users u ON u.id = pg.author_id
  LEFT JOIN media_variants av ON av.media_id = u.avatar_media_id AND av.variant = 'AVATAR_S'
  CROSS JOIN LATERAL (
    SELECT jsonb_agg(jsonb_build_object(
             'id', ma.id, 'kind', ma.kind, 'blurhash', ma.blurhash,
             'feedKey', fv.object_key, 'thumbKey', tv.object_key,
             'posterKey', pv.object_key, 'videoKey', vv.object_key, 'durationMs', ma.duration_ms,
             'width', COALESCE(fv.width, vv.width), 'height', COALESCE(fv.height, vv.height))
             ORDER BY pm.position) AS media
    FROM post_media pm
    JOIN media_assets ma ON ma.id = pm.media_id
    LEFT JOIN media_variants fv ON fv.media_id = ma.id AND fv.variant = 'FEED'
    LEFT JOIN media_variants tv ON tv.media_id = ma.id AND tv.variant = 'THUMB'
    LEFT JOIN media_variants pv ON pv.media_id = ma.id AND pv.variant = 'POSTER'
    LEFT JOIN media_variants vv ON vv.media_id = ma.id AND vv.variant = 'VIDEO_720'
    WHERE pm.post_id = pg.id
  ) m
  ORDER BY pg.created_at DESC, pg.id DESC;
END $$;
-- @end-function

-- @function feed/fn_get_post.sql
-- GET /posts/:id (post detail, shared links). Feed-item shape plus status and is_mine.
-- Others see PUBLISHED posts only (fn__assert_post_visible); the author also sees their own
-- PROCESSING and FAILED posts. Hidden and deleted posts are JA404 for everyone.
-- `media` is as in fn_get_home_feed, and additionally carries each item's own status, which is
-- what tells the author's screen that one photo of a carousel is still being processed.
CREATE OR REPLACE FUNCTION fn_get_post(p_viewer_id uuid, p_post_id uuid)
RETURNS TABLE (
  post_id uuid, status post_status, type post_type, created_at timestamptz, caption varchar,
  like_count int, comment_count int, liked_by_me boolean, is_mine boolean,
  author_id uuid, author_username citext, author_display_name varchar, author_avatar_key text,
  media jsonb)
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
BEGIN
  PERFORM fn__assert_active_user(p_viewer_id);

  IF NOT EXISTS (SELECT 1 FROM posts p WHERE p.id = p_post_id AND p.author_id = p_viewer_id
                 AND p.status IN ('PROCESSING', 'PUBLISHED', 'FAILED')) THEN
    PERFORM fn__assert_post_visible(p_viewer_id, p_post_id);
  END IF;

  RETURN QUERY
  SELECT p.id, p.status, p.type, p.created_at, p.caption, p.like_count, p.comment_count,
         EXISTS (SELECT 1 FROM likes l WHERE l.user_id = p_viewer_id AND l.post_id = p.id),
         p.author_id = p_viewer_id,
         u.id, u.username, u.display_name, av.object_key,
         (SELECT jsonb_agg(jsonb_build_object(
                   'id', ma.id, 'kind', ma.kind, 'status', ma.status, 'blurhash', ma.blurhash,
                   'feedKey', fv.object_key, 'thumbKey', tv.object_key,
                   'posterKey', pv.object_key, 'videoKey', vv.object_key, 'durationMs', ma.duration_ms,
                   'width', COALESCE(fv.width, vv.width), 'height', COALESCE(fv.height, vv.height))
                   ORDER BY pm.position)
          FROM post_media pm
          JOIN media_assets ma ON ma.id = pm.media_id
          LEFT JOIN media_variants fv ON fv.media_id = ma.id AND fv.variant = 'FEED'
          LEFT JOIN media_variants tv ON tv.media_id = ma.id AND tv.variant = 'THUMB'
          LEFT JOIN media_variants pv ON pv.media_id = ma.id AND pv.variant = 'POSTER'
          LEFT JOIN media_variants vv ON vv.media_id = ma.id AND vv.variant = 'VIDEO_720'
          WHERE pm.post_id = p.id)
  FROM posts p
  JOIN users u ON u.id = p.author_id
  LEFT JOIN media_variants av ON av.media_id = u.avatar_media_id AND av.variant = 'AVATAR_S'
  WHERE p.id = p_post_id;
END $$;
-- @end-function

-- @function feed/fn_get_profile_posts.sql
-- GET /users/:username/posts (profile grid, BR-PR-01). Newest first, keyset paging. Other people
-- see PUBLISHED posts; on their own profile the viewer also sees PROCESSING and FAILED posts, and
-- HIDDEN ones (shown as "Removed for violating Community Guidelines", App Flow §10.3).
-- JA404 under the same rules as fn_get_profile; empty when the viewer blocked the profile.
-- `type` and `media_count` are what the tile badges are drawn from: a play triangle on a video
-- (BR-CT-07) and a carousel marker when the post holds more than one photo (BR-CT-09).
CREATE OR REPLACE FUNCTION fn_get_profile_posts(
  p_viewer_id   uuid,
  p_username    text,
  p_cursor_time timestamptz DEFAULT NULL,
  p_cursor_id   uuid        DEFAULT NULL,
  p_limit       int         DEFAULT 20)
RETURNS TABLE (
  post_id uuid, status post_status, type post_type, thumb_key text, blurhash varchar,
  media_count int, created_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  t record;
  c record := fn__cursor(p_cursor_time, p_cursor_id, p_limit);
BEGIN
  PERFORM fn__assert_active_user(p_viewer_id);
  t := fn__resolve_profile(p_viewer_id, p_username);
  IF t.blocked_by_me THEN
    RETURN;
  END IF;

  IF t.target_id = p_viewer_id THEN
    RETURN QUERY
    SELECT p.id, p.status, p.type, tv.object_key, ma.blurhash,
           (SELECT count(*)::int FROM post_media x WHERE x.post_id = p.id), p.created_at
    FROM posts p
    LEFT JOIN post_media pm ON pm.post_id = p.id AND pm.position = 0
    LEFT JOIN media_assets ma ON ma.id = pm.media_id
    LEFT JOIN media_variants tv ON tv.media_id = pm.media_id AND tv.variant = 'THUMB'
    WHERE p.author_id = p_viewer_id
      AND p.status IN ('PROCESSING', 'PUBLISHED', 'FAILED', 'HIDDEN')
      AND (p.created_at, p.id) < (c.cursor_time, c.cursor_id)
    ORDER BY p.created_at DESC, p.id DESC
    LIMIT c.page_limit;
  ELSE
    RETURN QUERY
    SELECT p.id, p.status, p.type, tv.object_key, ma.blurhash,
           (SELECT count(*)::int FROM post_media x WHERE x.post_id = p.id), p.created_at
    FROM posts p
    LEFT JOIN post_media pm ON pm.post_id = p.id AND pm.position = 0
    LEFT JOIN media_assets ma ON ma.id = pm.media_id
    LEFT JOIN media_variants tv ON tv.media_id = pm.media_id AND tv.variant = 'THUMB'
    WHERE p.author_id = t.target_id
      AND p.status = 'PUBLISHED'
      AND (p.created_at, p.id) < (c.cursor_time, c.cursor_id)
    ORDER BY p.created_at DESC, p.id DESC
    LIMIT c.page_limit;
  END IF;
END $$;
-- @end-function

-- @function maintenance/fn_maint_reconcile_counters.sql
-- Daily 02:00 (Schema §1 "Counters"): recomputes the denormalised counters of rows that changed
-- since p_since and fixes any that drifted. NULL means the last 25 hours (the daily run); pass
-- '-infinity' for a full recount, which locks every post and user row: off-hours only.
-- Returns how many rows were wrong (reported as a metric; it should stay 0).
--   users.follower_count / following_count  rows in follows
--   users.post_count                        PUBLISHED posts
--   posts.like_count                        rows in likes
--   posts.comment_count                     visible comments: neither deleted nor hidden, and
--                                           not sitting under a parent that is (a reply is only
--                                           ever read through its parent, BR-FD-08)
--   comments.reply_count                    visible replies to a top-level comment
-- Rows are locked (posts first, then users, the order the procedures use) before counting, so a
-- concurrent like or follow is either fully counted or applies its own +1 / -1 afterwards.
CREATE OR REPLACE FUNCTION fn_maint_reconcile_counters(p_since timestamptz DEFAULT NULL)
RETURNS TABLE (drift int)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  v_since timestamptz := COALESCE(p_since, now() - INTERVAL '25 hours');
  v_posts uuid[];
  v_users uuid[];
  v_drift int := 0;
  v_rows  int;
BEGIN
  SELECT array_agg(c.id ORDER BY c.id) INTO v_posts FROM (
    SELECT p.id FROM posts p WHERE p.updated_at >= v_since OR p.created_at >= v_since
    UNION SELECT l.post_id FROM likes l WHERE l.created_at >= v_since
    UNION SELECT k.post_id FROM comments k WHERE k.created_at >= v_since
  ) c;
  PERFORM 1 FROM posts p WHERE p.id = ANY (COALESCE(v_posts, '{}')) ORDER BY p.id FOR UPDATE;

  UPDATE posts p SET like_count = a.likes, comment_count = a.comments
  FROM (
    SELECT x.id,
           (SELECT count(*)::int FROM likes l WHERE l.post_id = x.id) AS likes,
           (SELECT count(*)::int FROM comments k
            LEFT JOIN comments pk ON pk.id = k.parent_id
            WHERE k.post_id = x.id AND k.deleted_at IS NULL AND k.hidden_at IS NULL
              AND (k.parent_id IS NULL OR (pk.deleted_at IS NULL AND pk.hidden_at IS NULL))) AS comments
    FROM posts x WHERE x.id = ANY (COALESCE(v_posts, '{}'))
  ) a
  WHERE p.id = a.id AND (p.like_count, p.comment_count) IS DISTINCT FROM (a.likes, a.comments);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_drift := v_drift + v_rows;

  -- reply_count on the top-level comments of those posts (BR-FD-08). Independent of whether the
  -- parent itself is hidden: it counts the replies' own state, which is what "N replies" means
  -- once the parent is back.
  UPDATE comments k SET reply_count = a.replies
  FROM (
    SELECT x.id,
           (SELECT count(*)::int FROM comments r
            WHERE r.parent_id = x.id AND r.deleted_at IS NULL AND r.hidden_at IS NULL) AS replies
    FROM comments x
    WHERE x.post_id = ANY (COALESCE(v_posts, '{}')) AND x.parent_id IS NULL
  ) a
  WHERE k.id = a.id AND k.reply_count IS DISTINCT FROM a.replies;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_drift := v_drift + v_rows;

  SELECT array_agg(c.id ORDER BY c.id) INTO v_users FROM (
    SELECT u.id FROM users u WHERE u.updated_at >= v_since OR u.created_at >= v_since
    UNION SELECT f.follower_id FROM follows f WHERE f.created_at >= v_since
    UNION SELECT f.following_id FROM follows f WHERE f.created_at >= v_since
    UNION SELECT p.author_id FROM posts p WHERE p.updated_at >= v_since
  ) c;
  PERFORM 1 FROM users u WHERE u.id = ANY (COALESCE(v_users, '{}')) ORDER BY u.id FOR UPDATE;

  UPDATE users u SET follower_count = a.followers, following_count = a.following, post_count = a.posts
  FROM (
    SELECT x.id,
           (SELECT count(*)::int FROM follows f WHERE f.following_id = x.id) AS followers,
           (SELECT count(*)::int FROM follows f WHERE f.follower_id = x.id) AS following,
           (SELECT count(*)::int FROM posts p WHERE p.author_id = x.id AND p.status = 'PUBLISHED') AS posts
    FROM users x WHERE x.id = ANY (COALESCE(v_users, '{}'))
  ) a
  WHERE u.id = a.id
    AND (u.follower_count, u.following_count, u.post_count) IS DISTINCT FROM (a.followers, a.following, a.posts);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_drift := v_drift + v_rows;

  RETURN QUERY SELECT v_drift;
END $$;
-- @end-function

-- @function posts/fn_create_post.sql
-- POST /posts (BR-CT-01, TRD §9, API-08). Creates the post as PROCESSING with its media; the API
-- enqueues media_to_process after commit. The post publishes itself once every one of its media
-- items is READY (fn_complete_media_processing), so a carousel appears only when complete.
--
-- Media (BR-CT-09, BR-CT-10): either 1-10 photos, in the order given, or exactly one video —
-- never a mix. The post's type follows the media, PHOTO or VIDEO.
--
-- Hashtags in the caption become rows in post_hashtags (BR-FD-10, fn__sync_post_hashtags).
--
-- Idempotency-Key: a repeat with the same key and request hash returns the original post
-- (replayed = true, nothing to process); the same key with a different request is JA409.
CREATE OR REPLACE FUNCTION fn_create_post(
  p_viewer_id       uuid,
  p_media_ids       uuid[],
  p_caption         text,
  p_idempotency_key text,
  p_request_hash    text)
RETURNS TABLE (
  post_id uuid, status post_status, type post_type, caption varchar, created_at timestamptz,
  media_to_process uuid[], replayed boolean)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  c_max_media constant int := 10;
  c_route     constant text := 'POST /posts';
  v_replay  jsonb;
  v_post_id uuid;
  v_caption text := NULLIF(btrim(p_caption), '');
  v_media   record;
  v_videos  int := 0;
  v_type    post_type;
BEGIN
  PERFORM fn__assert_active_user(p_viewer_id);

  IF p_idempotency_key IS NOT NULL THEN
    v_replay := fn__claim_idempotency_key(p_viewer_id, p_idempotency_key, c_route, p_request_hash);
    IF v_replay IS NOT NULL THEN
      RETURN QUERY
      SELECT p.id, p.status, p.type, p.caption, p.created_at, '{}'::uuid[], true
      FROM posts p WHERE p.id = (v_replay->>'postId')::uuid;
      RETURN;
    END IF;
  END IF;

  IF length(v_caption) > 2200 THEN
    RAISE EXCEPTION USING ERRCODE = 'JA400', MESSAGE = 'CAPTION_TOO_LONG';
  END IF;
  IF cardinality(p_media_ids) IS NULL OR cardinality(p_media_ids) < 1
     OR cardinality(p_media_ids) > c_max_media THEN
    RAISE EXCEPTION USING ERRCODE = 'JA400', MESSAGE = 'MEDIA_NOT_ATTACHABLE';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(p_media_ids) AS ids(id) GROUP BY ids.id HAVING count(*) > 1) THEN
    RAISE EXCEPTION USING ERRCODE = 'JA400', MESSAGE = 'MEDIA_NOT_ATTACHABLE';
  END IF;

  FOR v_media IN
    SELECT m.id, m.owner_id, m.purpose, m.status, m.kind FROM media_assets m
    WHERE m.id = ANY (p_media_ids) ORDER BY m.id FOR UPDATE
  LOOP
    IF v_media.owner_id <> p_viewer_id THEN
      RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'MEDIA_NOT_FOUND';
    END IF;
    IF v_media.purpose <> 'POST' OR v_media.status <> 'PENDING_UPLOAD'
       OR EXISTS (SELECT 1 FROM post_media pm WHERE pm.media_id = v_media.id) THEN
      RAISE EXCEPTION USING ERRCODE = 'JA400', MESSAGE = 'MEDIA_NOT_ATTACHABLE';
    END IF;
    IF v_media.kind = 'VIDEO' THEN
      v_videos := v_videos + 1;
    END IF;
  END LOOP;
  IF (SELECT count(*) FROM media_assets m WHERE m.id = ANY (p_media_ids)) <> cardinality(p_media_ids) THEN
    RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'MEDIA_NOT_FOUND';
  END IF;

  -- BR-CT-10: all photos, or one single video.
  IF v_videos = 0 THEN
    v_type := 'PHOTO';
  ELSIF v_videos = 1 AND cardinality(p_media_ids) = 1 THEN
    v_type := 'VIDEO';
  ELSE
    RAISE EXCEPTION USING ERRCODE = 'JA400', MESSAGE = 'MEDIA_KINDS_MIXED';
  END IF;

  INSERT INTO posts (author_id, type, caption) VALUES (p_viewer_id, v_type, v_caption)
  RETURNING id INTO v_post_id;

  INSERT INTO post_media (post_id, media_id, position)
  SELECT v_post_id, ids.media_id, (ids.ord - 1)::smallint
  FROM unnest(p_media_ids) WITH ORDINALITY AS ids(media_id, ord);

  UPDATE media_assets m SET status = 'UPLOADED', uploaded_at = now() WHERE m.id = ANY (p_media_ids);

  PERFORM fn__sync_post_hashtags(v_post_id, v_caption);

  IF p_idempotency_key IS NOT NULL THEN
    UPDATE idempotency_keys k SET response_body = jsonb_build_object('postId', v_post_id)
    WHERE k.user_id = p_viewer_id AND k.key = p_idempotency_key;
  END IF;

  RETURN QUERY
  SELECT p.id, p.status, p.type, p.caption, p.created_at, p_media_ids, false
  FROM posts p WHERE p.id = v_post_id;
END $$;
-- @end-function

-- @function posts/fn_update_post_caption.sql
-- PATCH /posts/:id (BR-CT-05, Could). Author only; hidden and deleted posts are not editable.
-- The post's hashtags are rewritten from the new caption (BR-FD-10), so editing a tag out of a
-- caption also takes the post out of that tag's list.
CREATE OR REPLACE FUNCTION fn_update_post_caption(p_viewer_id uuid, p_post_id uuid, p_caption text)
RETURNS TABLE (post_id uuid, caption varchar, updated_at timestamptz)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  v_author_id uuid;
  v_status    post_status;
  v_caption   text := NULLIF(btrim(p_caption), '');
BEGIN
  PERFORM fn__assert_active_user(p_viewer_id);

  SELECT p.author_id, p.status INTO v_author_id, v_status FROM posts p WHERE p.id = p_post_id FOR UPDATE;
  IF NOT FOUND OR v_status IN ('HIDDEN', 'DELETED') THEN
    RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'POST_NOT_FOUND';
  END IF;
  IF v_author_id <> p_viewer_id THEN
    PERFORM fn__assert_post_visible(p_viewer_id, p_post_id);
    RAISE EXCEPTION USING ERRCODE = 'JA403', MESSAGE = 'NOT_OWNER';
  END IF;
  IF length(v_caption) > 2200 THEN
    RAISE EXCEPTION USING ERRCODE = 'JA400', MESSAGE = 'CAPTION_TOO_LONG';
  END IF;

  UPDATE posts p SET caption = v_caption WHERE p.id = p_post_id;
  PERFORM fn__sync_post_hashtags(p_post_id, v_caption);

  RETURN QUERY
  SELECT p.id, p.caption, p.updated_at FROM posts p WHERE p.id = p_post_id;
END $$;
-- @end-function

-- @function media/fn_complete_media_processing.sql
-- Media worker, after sharp produced the variants (TRD §9). Stores the variants, marks the asset
-- READY and publishes its post once every media item of the post is READY (post_count + 1).
-- p_variants: [{ "variant": "FEED", "objectKey": "...", "width": 1080, "height": 1350,
--                "mimeType": "image/webp", "byteSize": 123456 }, ...]
-- p_duration_ms: video only (BR-CT-08), the length of the rendition that was produced. A CHECK
-- refuses it on an image and caps it at 65 s.
-- Safe to retry: a READY asset returns post_published = false. If the post was deleted while
-- processing, the variants just written are queued for deletion and nothing is published.
CREATE OR REPLACE FUNCTION fn_complete_media_processing(
  p_media_id uuid,
  p_width    int,
  p_height   int,
  p_blurhash text,
  p_variants jsonb,
  p_duration_ms int DEFAULT NULL)
RETURNS TABLE (post_id uuid, post_published boolean, author_id uuid)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
#variable_conflict use_column
DECLARE
  m         media_assets%ROWTYPE;
  v_post_id uuid;
  v_prefix  text;
  v_rows    int;
BEGIN
  SELECT * INTO m FROM media_assets a WHERE a.id = p_media_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'JA404', MESSAGE = 'MEDIA_NOT_FOUND';
  END IF;

  SELECT pm.post_id INTO v_post_id FROM post_media pm WHERE pm.media_id = p_media_id;

  IF m.status = 'DELETED' THEN
    PERFORM fn__queue_media_deletion(ARRAY[p_media_id]);
    RETURN QUERY SELECT v_post_id, false, m.owner_id; RETURN;
  ELSIF m.status = 'READY' THEN
    RETURN QUERY SELECT v_post_id, false, m.owner_id; RETURN;
  ELSIF m.status NOT IN ('UPLOADED', 'PROCESSING') THEN
    RAISE EXCEPTION USING ERRCODE = 'JA409', MESSAGE = 'INVALID_STATE';
  END IF;

  v_prefix := 'users/' || m.owner_id || '/media/' || m.id || '/';
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_variants) v WHERE NOT starts_with(v->>'objectKey', v_prefix)) THEN
    RAISE EXCEPTION USING ERRCODE = 'JA400', MESSAGE = 'INVALID_VARIANT_KEY';
  END IF;

  INSERT INTO media_variants (media_id, variant, object_key, width, height, mime_type, byte_size)
  SELECT p_media_id, v.variant::media_variant_type, v."objectKey", v.width, v.height, v."mimeType", v."byteSize"
  FROM jsonb_to_recordset(p_variants)
    AS v(variant text, "objectKey" text, width int, height int, "mimeType" text, "byteSize" int)
  ON CONFLICT (media_id, variant) DO UPDATE
    SET object_key = EXCLUDED.object_key, width = EXCLUDED.width, height = EXCLUDED.height,
        mime_type = EXCLUDED.mime_type, byte_size = EXCLUDED.byte_size;

  UPDATE media_assets a
  SET status = 'READY', width = p_width, height = p_height, blurhash = p_blurhash,
      duration_ms = COALESCE(p_duration_ms, a.duration_ms),
      failure_reason = NULL, processed_at = now()
  WHERE a.id = p_media_id;

  IF v_post_id IS NULL THEN
    RETURN QUERY SELECT NULL::uuid, false, m.owner_id; RETURN;
  END IF;

  UPDATE posts p SET status = 'PUBLISHED', published_at = now()
  WHERE p.id = v_post_id AND p.status = 'PROCESSING'
    AND NOT EXISTS (SELECT 1 FROM post_media pm JOIN media_assets a ON a.id = pm.media_id
                    WHERE pm.post_id = v_post_id AND a.status <> 'READY');
  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF v_rows = 1 THEN
    UPDATE users u SET post_count = u.post_count + 1 WHERE u.id = m.owner_id;
  END IF;

  RETURN QUERY SELECT v_post_id, v_rows = 1, m.owner_id;
END $$;
-- @end-function

-- @grants (prisma/grants.sql)
-- Runtime-role grants (Schema §9, TRD SP-05 / SR-01). Idempotent: appended to every
-- migration that adds functions. Table column grants live in the migration that adds the table.

-- Only jamii_app (and the owner) may use the schema.
REVOKE ALL ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO jamii_app;

-- New functions are not executable by PUBLIC. Extension functions (citext, pg_trgm) keep
-- their PUBLIC grant: jamii_app's simple reads need the citext operators.
ALTER DEFAULT PRIVILEGES FOR ROLE jamii_owner IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;

-- fn_*: EXECUTE for jamii_app. fn__* (internal helpers): nobody but the owner.
DO $$
DECLARE
  f record;
BEGIN
  FOR f IN
    SELECT p.oid::regprocedure AS sig, p.proname
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname LIKE 'fn\_%'
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f.sig);
    IF f.proname LIKE 'fn\_\_%' THEN
      EXECUTE format('REVOKE ALL ON FUNCTION %s FROM jamii_app', f.sig);
    ELSE
      EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO jamii_app', f.sig);
    END IF;
  END LOOP;
END $$;
-- @end-grants
